#include "nix/store/builtins.hh"
#include "nix/store/store-api.hh"
#include "nix/util/file-system.hh"
#include "nix/util/processes.hh"
#include "nix/util/strings.hh"
#include <nlohmann/json.hpp>
#include <fstream>
#include <sstream>

using json = nlohmann::json;

namespace nix {

/**
 * Parse a Makefile-style dependency file (.d file) generated by gcc -MMD
 * Format: target: dep1 dep2 dep3 \
 *         dep4 dep5
 */
static std::vector<std::string> parseDependencyFile(const Path & depfile)
{
    std::vector<std::string> headers;

    std::ifstream file(depfile);
    if (!file.is_open())
        return headers;

    std::string line;
    std::ostringstream fullContent;

    // Read all lines, handling line continuations
    while (std::getline(file, line)) {
        // Remove trailing backslash for line continuation
        if (!line.empty() && line.back() == '\\') {
            line.pop_back();
            fullContent << line << " ";
        } else {
            fullContent << line;
        }
    }

    std::string content = fullContent.str();

    // Find the colon separator (target: dependencies)
    auto colonPos = content.find(':');
    if (colonPos == std::string::npos)
        return headers;

    // Get everything after the colon
    std::string deps = content.substr(colonPos + 1);

    // Split by whitespace
    std::istringstream iss(deps);
    std::string token;
    while (iss >> token) {
        // Skip empty tokens
        if (!token.empty()) {
            headers.push_back(token);
        }
    }

    return headers;
}

/**
 * Builtin builder: cproject-discover
 *
 * Runs compiler with -M -MF to discover header dependencies for all source files.
 * Outputs JSON with the discovered dependencies.
 *
 * Environment variables:
 * - sources: Semicolon-separated list of source files (relative to root)
 * - compiler: Path to compiler executable
 * - root: Root directory of the project
 * - pkgConfigFlags: Optional path to pkg-config flags JSON
 *
 * Output (JSON):
 * {
 *   "sources": [
 *     {
 *       "file": "src/main.cpp",
 *       "headers": ["/nix/store/.../foo.h", "include/bar.h", ...]
 *     },
 *     ...
 *   ]
 * }
 */
static void builtinCProjectDiscover(const BuiltinBuilderContext & ctx)
{
    auto out = get(ctx.drv.outputs, "out");
    if (!out)
        throw Error("'builtin:cproject-discover' requires an 'out' output");

    auto outputPath = ctx.outputs.at("out");

    // Extract configuration from derivation environment
    auto sourcesStr = ctx.drv.env.at("sources");
    auto compiler = ctx.drv.env.at("compiler");
    auto root = ctx.drv.env.at("root");

    // Parse sources list
    std::vector<std::string> sources;
    std::istringstream sourcesStream(sourcesStr);
    std::string source;
    while (std::getline(sourcesStream, source, ';')) {
        if (!source.empty())
            sources.push_back(source);
    }

    // Load pkg-config flags if provided
    std::vector<std::string> pkgConfigCflags;
    auto pkgConfigFlagsIt = ctx.drv.env.find("pkgConfigFlags");
    if (pkgConfigFlagsIt != ctx.drv.env.end()) {
        // TODO: Read and parse pkg-config flags JSON
        // For now, placeholder
    }

    // Create temporary directory for .d files
    Path tempDir = createTempDir();

    // Discover dependencies for each source file
    json result = json::object();
    json sourcesArray = json::array();

    for (const auto & srcFile : sources) {
        Path fullSrcPath = root + "/" + srcFile;

        // Generate dependency file path
        Path depFile = tempDir + "/" + std::to_string(std::hash<std::string>{}(srcFile)) + ".d";

        // Run compiler with -M -MF to generate dependencies
        // gcc -M -MF depfile source.c
        Strings args = {
            "-M",
            "-MF", depFile
        };

        // Add pkg-config flags
        for (const auto & flag : pkgConfigCflags) {
            args.push_back(flag);
        }

        // Add source file
        args.push_back(fullSrcPath);

        try {
            // Run the compiler
            auto result = runProgram(RunOptions{
                .program = compiler,
                .args = args,
                .mergeStderrToStdout = true
            });

            // Parse the generated dependency file
            auto headers = parseDependencyFile(depFile);

            // Add to result
            json sourceEntry = {
                {"file", srcFile},
                {"headers", headers}
            };
            sourcesArray.push_back(sourceEntry);

        } catch (Error & e) {
            warn("failed to discover dependencies for %s: %s", srcFile, e.what());
            // Add entry with empty headers
            json sourceEntry = {
                {"file", srcFile},
                {"headers", json::array()}
            };
            sourcesArray.push_back(sourceEntry);
        }
    }

    result["sources"] = sourcesArray;

    // Write result JSON to output
    createDirs(outputPath);
    Path jsonPath = outputPath + "/deps.json";
    std::ofstream outFile(jsonPath);
    outFile << result.dump(2);
    outFile.close();

    // Clean up temp directory
    deletePath(tempDir);
}

static RegisterBuiltinBuilder registerCProjectDiscover("cproject-discover", builtinCProjectDiscover);

} // namespace nix
